# Selection owns a new list spine; selected records retain shared identity.
class QueryRecord:

    def __init__(self, key: str, value: int):
        self.key = key
        self.value = value

def query_select(rows: list[QueryRecord], predicate: Callable[[QueryRecord], int]) -> list[QueryRecord]:
    selected: list[QueryRecord] = []
    for row in rows:
        if predicate(row):
            selected.append(row)
    return selected

def query_total(rows: list[QueryRecord], measure: Callable[[QueryRecord], int]) -> int:
    total: int = 0
    for row in rows:
        total += measure(row)
    return total
